import {mkdtemp,writeFile,chmod,rm} from 'node:fs/promises';
import {randomUUID,createHash} from 'node:crypto';
import path from 'node:path';
import os from 'node:os';
const sha=x=>createHash('sha256').update(x).digest('hex');
export async function paqueteOperativo(t,{cliente=randomUUID(),nombre='CLIENTE SINTETICO'}={}){
 const dir=await mkdtemp(path.join(os.tmpdir(),'ims-op-abiertos-'));await chmod(dir,0o700);t?.after(()=>rm(dir,{recursive:true,force:true}));
 const prep=path.join(dir,'prep'),planDir=path.join(dir,'plan');for(const d of [prep,planDir])await writeDir(d);
 const corte=randomUUID(),inv1=randomUUID(),inv2=randomUUID(),pendiente=randomUUID(),a='ORIGEN_SINTETICO_'+randomUUID().replaceAll('-',''),b='ORIGEN_PENDIENTE_'+randomUUID().replaceAll('-','');
 const lineas=Array.from({length:5},(_,n)=>{const pending=n>=3,id=n<2?inv1:inv2,origen={corte_id:corte,origen_drive:pending?b:a,hoja_id:3,fila:pending?n-1:n+2,zona_horaria:'America/Guayaquil'};return {linea_id:randomUUID(),referencia_copia:sha(JSON.stringify(['SELECCION_ACTUAL',corte,origen.origen_drive,origen.hoja_id,origen.fila])),ambito:'SELECCION_ACTUAL',origen,numero:pending?n-2:n<2?n+1:1,sku:'00001',codigo_original:pending?null:'111126_SINTETICO',inventario_id:pending?null:id,...(pending?{pendiente_id:pendiente,pendiente_de_iniciar:true}:{}),cliente_id:cliente,conteo_1:n===0?'0.000000000':n===2?'1.234567891':null,conteo_2:null,conteo_final:n===2?'2.000000000':null,depot:n===0?'9007199254740993.123456789':'1.000000000',ajuste:n===0?'-0.125000000':null,fecha_inicio:pending?null:n===2?'2026-11-12':'2026-11-11',fecha_fin:null,descripcion:'Descripción <b>literal</b>',posicion:'A-'+n,serie:'',lote:'001',unidad:'UN',observacion:'Nota original ñ '+n,nueva_posicion:'',motivo:'',justificacion:'',abc:'A',despacho:'',partida:'',categoria:'',estado_mercancia:'',bloqueos:[],avisos:[],aprobado_para_importar:false};});
 const productos=lineas.map(l=>({referencia_copia:l.referencia_copia,ambito:l.ambito,origen:l.origen,estado_captura:'COMPLETO',sku_propuesto:l.sku,codigo_operativo_original:l.codigo_original,clientes_panel_referencia:[nombre],cantidades:Object.fromEntries([['depot',l.depot],['c1',l.conteo_1],['c2',null],['c3',l.conteo_final],['ajuste',l.ajuste],['fisico',null]].map(([k,v])=>[k,{estado:v===null?'VACIO':'EXACTA',valor_decimal:v}])),fila_original:{fila:l.origen.fila,celdas:[{columna:7,tipo:'s',valor:l.sku},{columna:22,tipo:l.conteo_1===null?'z':'n',valor:l.conteo_1}]},aprobado_para_importar:false}));
 const zip=path.join(dir,'fuente.zip');await put(zip,'ZIP SINTETICO');const zipSha=sha('ZIP SINTETICO');
 const archivos={'lineas_candidatas_NO_IMPORTAR.jsonl':productos.map(x=>JSON.stringify(x)+'\n').join(''),'filas_auxiliares_NO_IMPORTAR.jsonl':'','esquemas_NO_COMPARTIR.json':'[]'};for(const [n,s] of Object.entries(archivos))await put(path.join(prep,n),s);
 const m={formato:'ims-abiertos-preparacion-privada-v1',corte_id:corte,archivo_zip:zip,sha256_zip:zipSha,archivos_sha256:Object.fromEntries(Object.entries(archivos).map(([n,s])=>[n,sha(s)])),aprobado_para_importar:false};const raw=JSON.stringify(m);await put(path.join(prep,'preparacion_NO_IMPORTAR.json'),raw);const copia=sha(raw);
 const f=(origen,n,pending=false)=>({origen_drive:origen,ambito:'SELECCION_ACTUAL',sede:'UIO',cliente_id:cliente,cliente_panel:nombre,productos:n,bloqueos:{},requiere_delta_final:false,pendiente_de_iniciar:pending});
 const header=(id,n,fecha)=>({inventario_id:id,origen_drive:a,ambito:'SELECCION_ACTUAL',sede:'UIO',cliente_id:cliente,cliente_panel:nombre,productos:n,codigo_operativo:'111126_SINTETICO',fecha_inicio:fecha,estado_destino:'EN_PROCESO',bloqueos:{},sin_bloqueos_estructurales:true,requiere_delta_final:false});
 const texto=lineas.map(x=>JSON.stringify(x)+'\n').join('');await put(path.join(planDir,'lineas_operativas_NO_ACTIVAR.jsonl'),texto);
 const p={formato:'ims-abiertos-plan-operativo-v2',copia_id:copia,corte_id:corte,fuentes:[f(a,3),f(b,2,true)],inventarios:[header(inv1,2,'2026-11-11'),header(inv2,1,'2026-11-12')],productos:5,auxiliares_conservados:0,auxiliares_sha256:sha(''),proyecciones_sha256:sha(texto),requiere_delta_final:false,aprobado_para_importar:false,corte_elegido:{formato:'ims-abiertos-corte-elegido-v1',corte_id:corte,copia_id:copia,sha256_zip:zipSha,usar_capturas_guardadas:true,solicitar_nueva_extraccion_google:false}};const planRaw=JSON.stringify(p);await put(path.join(planDir,'plan_operativo_NO_ACTIVAR.json'),planRaw);
 return {dir,prep,planDir,p,lineas,corte,inv1,inv2,pendiente,cliente,nombre,solicitud:{directorio:planDir,preparacion:prep,planId:sha(planRaw),copiaId:copia,corteId:corte}};
}
async function put(f,s){await writeFile(f,s,{mode:0o600});}
async function writeDir(d){const {mkdir}=await import('node:fs/promises');await mkdir(d,{mode:0o700});}
